const current = $input.first().json;
function parseResponse(raw) {
  if (raw.error) throw new Error('MODEL_CALL_FAILED');
  if (raw.status && raw.status !== 'completed') throw new Error('MODEL_OUTPUT_INCOMPLETE');
  const texts = [];
  for (const output of Array.isArray(raw.output) ? raw.output : []) {
    if (output.status && output.status !== 'completed') throw new Error('MODEL_OUTPUT_INCOMPLETE');
    for (const part of Array.isArray(output.content) ? output.content : []) {
      if (part.type === 'refusal' || part.refusal) throw new Error('MODEL_REFUSAL');
      if (typeof part.text === 'string') texts.push(part.text);
    }
  }
  if (!texts.length && typeof raw.output_text === 'string') texts.push(raw.output_text);
  if (texts.length !== 1) throw new Error('MODEL_OUTPUT_INVALID');
  const text = texts[0].trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const result = JSON.parse(text);
  if (!result || typeof result !== 'object' || Array.isArray(result)) throw new Error('MODEL_OUTPUT_INVALID');
  return result;
}

const base = $('Kundenkontext laden').first().json;
try {
  const a = parseResponse(current);
  const list = x => Array.isArray(x) && x.every(v => typeof v === 'string' && v.length <= 300 && !v.includes('�'));
  if (!['login','billing','technical','other'].includes(a.category)
      || !['low','medium','high','critical'].includes(a.priority)
      || typeof a.summary !== 'string' || !a.summary.trim() || a.summary.length > 1000 || a.summary.includes('�')
      || typeof a.needs_review !== 'boolean'
      || !list(a.article_ids) || a.article_ids.length > 5
      || !a.article_ids.every(id => ['KB001','KB002','KB003','KB004','KB005'].includes(id))
      || !list(a.missing_information) || a.missing_information.length > 10
      || !list(a.risk_flags) || a.risk_flags.length > 10) throw new Error('CLASSIFICATION_SCHEMA_INVALID');
  const analysis = {category: a.category, priority: a.priority, summary: a.summary,
    article_ids: [...new Set(a.article_ids)], needs_review: a.needs_review,
    missing_information: a.missing_information, risk_flags: a.risk_flags};
  return [{json: {...base, classification_valid: true, analysis}}];
} catch (error) {
  return [{json: {...base, classification_valid: false, analysis: {},
    source_article_ids: [], draft: null, decision: 'review', status: 'technical_error',
    reason_codes: ['CLASSIFICATION_FAILED'], error_code: 'CLASSIFICATION_FAILED',
    error_message: 'KI-Aufruf oder Klassifikationsausgabe ungültig. Execution prüfen.'}}];
}

const current = $input.first().json;
return [{json: {...current.context, articles: current.articles,
  source_article_ids: current.articles.map(a => a.article_id)}}];

const c = $input.first().json;
// Alle Pfade liefern denselben Vertrag an den Hauptworkflow zurück.
if (c.status) {
  return [{json: {...c, prepare_answer: false}}];
}
if (!Array.isArray(c.articles) || c.articles.length === 0) {
  return [{json: {...c, prepare_answer: false, draft: null,
    decision: 'review', status: 'needs_review',
    source_article_ids: [], reason_codes: ['NO_APPROVED_KNOWLEDGE'],
    error_code: null, error_message: null}}];
}
return [{json: {...c, prepare_answer: true}}];
